function write_ws_biff8_cell(ba
/*:BufArray*/
, cell
/*:Cell*/
, R
/*:number*/
, C
/*:number*/
, opts) {
  var os = 16 + get_cell_style(opts.cellXfs, cell, opts);

  if (cell.v == null && !cell.bf) {
    write_biff_rec(ba, 0x0201
    /* Blank */
    , write_XLSCell(R, C, os));
    return;
  }

  if (cell.bf) write_biff_rec(ba, 0x0006
  /* Formula */
  , write_Formula(cell, R, C, opts, os));else switch (cell.t) {
    case 'd':
    case 'n':
      var v = cell.t == 'd' ? datenum(parseDate(cell.v)) : cell.v;
      /* TODO: emit RK as appropriate */

      write_biff_rec(ba, 0x0203
      /* Number */
      , write_Number(R, C, v, os, opts));
      break;

    case 'b':
    case 'e':
      write_biff_rec(ba, 0x0205
      /* BoolErr */
      , write_BoolErr(R, C, cell.v, os, opts, cell.t));
      break;

    /* TODO: codepage, sst */

    case 's':
    case 'str':
      if (opts.bookSST) {
        var isst = get_sst_id(opts.Strings, cell.v, opts.revStrings);
        write_biff_rec(ba, 0x00fd
        /* LabelSst */
        , write_LabelSst(R, C, isst, os, opts));
      } else write_biff_rec(ba, 0x0204
      /* Label */
      , write_Label(R, C, (cell.v || "").slice(0, 255), os, opts));

      break;

    default:
      write_biff_rec(ba, 0x0201
      /* Blank */
      , write_XLSCell(R, C, os));
  }
}
